            Console.WriteLine($"- Exactitud numerica: {F(exactNum, UmbralNumerica)} sobre {conCifras.Count} casos");
            Console.WriteLine($"- Casos {resultados.Count}; OK {resultados.Count(x => x.Ok)}; FALLA {resultados.Count(x => !x.Ok)}");
